# RLS fail-closed nas tabelas do ORC.5b — mesma política de 0002/0003/0004/0005.
# Helper repetido em vez de importado porque nome de módulo de migration começa
# com dígito e não é importável; é o padrão do repo.
#
# Vale para TODAS as oito, inclusive as de importação: a área de conferência
# guarda o arquivo de preço que a empresa subiu antes de qualquer decisão, e
# tabela de preço de concorrente vazando entre tenants é vazamento comercial —
# não é dado público como a base-mãe.
_TABLES = (
    "moduloorcamento_bancopreco",
    "moduloorcamento_pastacomposicao",
    "moduloorcamento_itembancopreco",
    "moduloorcamento_componentebancopreco",
    "moduloorcamento_importacaopreco",
    "moduloorcamento_linhaimportacao",
    "moduloorcamento_reprecificacao",
    "moduloorcamento_linhareprecificacao",
)
POLICY = "tenant_isolation"
USING_CLOSED = (
    "current_setting('app.rls_bypass', true) = 'on' "
    "OR tenant_id::text = current_setting('app.current_tenant', true)"
)


def enable_rls(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    with schema_editor.connection.cursor() as c:
        for table in _TABLES:
            c.execute(f'ALTER TABLE "{table}" ENABLE ROW LEVEL SECURITY;')
            c.execute(f'ALTER TABLE "{table}" FORCE ROW LEVEL SECURITY;')
            c.execute(f'DROP POLICY IF EXISTS {POLICY} ON "{table}";')
            c.execute(
                f'CREATE POLICY {POLICY} ON "{table}" '
                f"USING ({USING_CLOSED}) WITH CHECK ({USING_CLOSED});"
            )


def disable_rls(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    with schema_editor.connection.cursor() as c:
        for table in _TABLES:
            c.execute(f'DROP POLICY IF EXISTS {POLICY} ON "{table}";')
            c.execute(f'ALTER TABLE "{table}" NO FORCE ROW LEVEL SECURITY;')
            c.execute(f'ALTER TABLE "{table}" DISABLE ROW LEVEL SECURITY;')


